void BubbleSort(SLLNode *head)
{
    SLLNode *p, *q, *last;
    if (head == nullptr) return;
    last = nullptr;
    do{
        p = head;
        while (p->next != last)
        {
            q = p->next;
            if (p->data.key > q->data.key)
            {
                ElementType tmp = p->data;
                p->data = q->data;
                q->data = tmp;
                last = q;
            }
            p = p->next;
            q = q->next;
        }
    } while (last == nullptr || last == head->next);
}

void SortByGPA(SLLStudents *head)
{
    SLLStudent *p, *q, *last;
    if (head == nullptr) return;
    last = nullptr;
    do{
        p = head;
        while (p->next != last)
        {
            q = p->next;
            if (p->data.gpa < q->data.gpa)
            {
                Student tmp = p->data;
                p->data = q->data;
                q->data = tmp;
                last = q;
            }
            p = p->next;
            q = q->next;
        }
    } while (last == nullptr || last == head->next);
}

