void deleteFirst(SLLNode* &head)
{
    if (head == nullptr) return;
    if (head->next == head)
    {
        delete head;
        head = nullptr;
    }
    else
    {
        last = head;
        while (last->next != head) last = last->next;
        last->next = head->next;
        delete head;
        head = last->next;
    }
}

void deleteLast(SLLNode* &head)
{
    if (head == nullptr) return;
    if (head->next == head)
    {
        delete head;
        head = nullptr;
    }
    else
    {
        SLLNode *plast = head;
        while (plast->next->next != head) plast = plast->next;
        SLLNode *q = plast->next;
        plast->next = head;
        delete q;
    }
}

struct DLLNode
{
    ElementType data;
    DLLNode *prev, *next;
};

void insertBefore(DLLNode* &head, DLLNode *p, ElementType x)
{
    DLLNode *q,*p1;
    q = new DLLNode;
    q->data = x;
    //danh sách rỗng
    if (head == nullptr)
    {
        q->prev = nullptr;
        q->next = nullptr;
        head = q;
    }
    else
    {
        if (head == p) //thêm vào đầu
        {
            q->prev = nullptr;
            q->next = p;
            p->prev = q;
            head = q;
        }
        else
        {
            p1 = p->prev;
            q->prev = p1;
            p1->next = q;
            q->next = p;
            p->prev = q;
        }
    }
}

void delete(DLLNode* &head, DLLLNode *p)
{
    if (head == p) // xóa phần tử đầu
    {
        head = p->next;
        if (head != nullptr)
            head->prev = nullptr;
    }
    else
    {
        p->prev->next = p->next;
        if (p->next != nullptr)
            p->next->prev = p->prev;
    }
    delete p;
}

#include <list>
#include <iostream>

int main()
{
    std::list<int> myList{1, 2, 3};

    // Iterating through the list using forward iterators
    std::cout << "Forward iteration:\n";
    std::list<int>::iterator it;

    for (it = myList.begin(); it != myList.end(); it++)
        std::cout << *it << ' ';
    std::cout << '\n';

    // Iterating through the list using reverse iterators
    std::cout << "Reverse iteration:\n";
    std::list<int>::reverse_iterator rit;

    for (rit = myList.rbegin(); rit != myList.rend(); it++)
        std::cout << *rit << ' ';
    std::cout << '\n';

    return 0;
}

