    }

    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <list>
#include <algorithm>

bool compareDescending(int a, int b) {
    return a > b;
}

int main()
{
    std::list<int> myList = {5, 1, 4, 2, 3};

    std::cout << "Before sorting: ";
    for (int element : myList)
    {
        std::cout << element << " ";
    }

    std::cout << std::endl;

    myList.sort(compareDescending);

    std::cout << "After sorting: ";
    for (int element : myList)
    {
        std::cout << element << " ";
    }

    std::cout << std::endl;

    return 0;
}
